package ma.enset.smartdevcollab.service;
import ma.enset.smartdevcollab.entity.*; import ma.enset.smartdevcollab.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class UserService{ private final UserRepository repo; private final PasswordEncoder enc; public UserService(UserRepository repo, PasswordEncoder enc){this.repo=repo;this.enc=enc;} public List<User> all(){return repo.findAll();} public User byEmailOrDemo(String email){ if(email!=null) return repo.findByEmail(email).orElseGet(this::demo); return demo(); } public User demo(){ return repo.findByEmail("demo@smartdevcollab.com").orElseGet(()->repo.save(User.builder().fullName("Demo User").email("demo@smartdevcollab.com").password(enc.encode("123456")).role(Role.STUDENT).skillsText("Gestion projet, Documentation").build())); } }
